"""Recover bounds on the secret fair value t per item from the public leaderboard.

  pixi run python -m c2f.truth 2          # game 2 -> runs/truth_game_02.json + table

How: the leaderboard's /matchup cell for (X, Y) in a game is  net_X_vs_Y - net_Y_vs_X  (antisymmetric),
and /transactions tells us every charge a and whether it was accepted. Each pair's cell is a known
piecewise-constant function of the t's, so we keep, per item, only the t-intervals consistent with
every pair equation. Rejections are what carry information: a rejected fair charge contributes 2.5a,
a rejected fraud 0. Accepted charges contribute 2a either way (cap assumed not binding).

Two sources, combined: (1) the payout feed directly - a rejected charge still paid is fair (t >= a),
a rejected charge paid 0 whose size is known from an acceptance is fraud (t < a); (2) the matchup
equations above, which can narrow further but are dropped when inconsistent (e.g. the cap binds).

Output per item: t_lo (largest charge proven fair) and t_hi (smallest charge proven fraud, or inf).
"""

from __future__ import annotations

import collections
import itertools
import json
import sys

import requests

from c2f.feedback import B, teams, transactions
from c2f.submit import ROOT

TOL = 0.06


def _diff(a: float, acc: bool, t: float) -> float:
    """Contribution of one transaction to (issuer_net - reviewer_net) given t."""
    if a <= 0:
        return 0.0
    if a <= t + 1e-9:
        return 2 * a if acc else 2.5 * a
    return 2 * a if acc else 0.0


def payout_bounds(tx_list: list[dict]) -> dict[int, tuple[float, float | None]]:
    """Direct evidence from the payout feed, per item: (t_lo, t_hi or None).

    A rejected charge that was still paid (amount > 0) is proven fair: t >= amount. A rejected
    charge paid 0 whose size a is known from an acceptance is proven fraud: t < a.
    """
    acc: dict[tuple, float] = collections.defaultdict(float)
    rej: dict[tuple, list] = collections.defaultdict(list)
    for x in tx_list:
        key = (x["issuer"], x["line_item_index"])
        if x["accepted"]:
            acc[key] = max(acc[key], float(x["amount"]))
        else:
            rej[key].append(float(x["amount"]))
    items = sorted({x["line_item_index"] for x in tx_list})
    lo = {i: 0.0 for i in items}
    hi: dict[int, float | None] = {i: None for i in items}
    for (iss, i), amounts in rej.items():
        if max(amounts) > 0:
            lo[i] = max(lo[i], max(amounts))
        elif acc[(iss, i)] > 0:
            a = acc[(iss, i)]
            hi[i] = a if hi[i] is None else min(hi[i], a)
    return {i: (lo[i], hi[i]) for i in items}


def infer(game_id: int) -> dict[int, dict]:
    names = teams()
    tx: dict[tuple, dict] = {}
    for t in names:
        for x in transactions(game_id, t):
            tx[(x["issuer"], x["reviewer"], x["line_item_index"])] = x
    tx_list = list(tx.values())
    direct = payout_bounds(tx_list)
    games = [g["id"] for g in requests.get(f"{B}/games?completed_only=true&page_size=200", timeout=15).json()["items"]]
    gi = games.index(game_id)
    net = {}
    short = 0
    for t in names:
        for m in requests.get(f"{B}/matchup", params={"team": t}, timeout=15).json()["items"]:
            # A matchup row can lag the completed-games list: right after a game closes the
            # server may still serve cells without it (and a team that joined late is short
            # from the other end). The pair equations only ever NARROW the direct payout
            # bounds, so a missing cell costs precision, never correctness - skip it.
            cells = m.get("cells") or []
            if gi >= len(cells):
                short += 1
                continue
            net[(t, m["opponent"])] = cells[gi]
    if short:
        print(f"note: {short} matchup row(s) have no cell for game {game_id} yet - "
              f"using payout evidence only for those pairs (rerun `make truth G={game_id}` later to tighten)")

    items = sorted({x["line_item_index"] for x in tx_list})
    charges = {i: sorted({x["amount"] for x in tx_list if x["line_item_index"] == i and x["amount"] > 0}) for i in items}
    reps = {i: [0.0] + charges[i] for i in items}  # interval k: t in [reps[k], reps[k+1])
    feas = {i: set(range(len(reps[i]))) for i in items}
    for i in items:  # seed with the direct payout evidence; the pair equations can only narrow further
        d_lo, d_hi = direct[i]
        feas[i] = {k for k in feas[i] if reps[i][k] >= d_lo and (d_hi is None or reps[i][k] < d_hi)} or feas[i]
    by = collections.defaultdict(list)
    for x in tx_list:
        by[(x["issuer"], x["reviewer"])].append(x)

    def contrib(X: str, Y: str, i: int, k: int) -> float:
        t = reps[i][k]
        s = sum(_diff(x["amount"], x["accepted"], t) for x in by[(X, Y)] if x["line_item_index"] == i)
        s -= sum(_diff(x["amount"], x["accepted"], t) for x in by[(Y, X)] if x["line_item_index"] == i)
        return s

    eqs = []
    for (X, Y), v in net.items():
        if X >= Y:
            continue
        inv = [i for i in items if any(x["amount"] > 0 for x in by[(X, Y)] + by[(Y, X)] if x["line_item_index"] == i)]
        if inv:
            eqs.append((X, Y, v, inv))

    changed, rounds = True, 0
    while changed and rounds < 30:
        changed, rounds = False, rounds + 1
        for X, Y, v, inv in eqs:
            tabs = [{k: contrib(X, Y, i, k) for k in feas[i]} for i in inv]
            # exact, via subset-sum DP in cents over the distinct contribution values per item
            vals = [sorted({round(c * 100) for c in t.values()}) for t in tabs]
            n = len(inv)
            pre = [set() for _ in range(n + 1)]
            pre[0].add(0)
            for j in range(n):
                pre[j + 1] = {p + c for p in pre[j] for c in vals[j]}
            suf = [set() for _ in range(n + 1)]
            suf[n].add(0)
            for j in range(n - 1, -1, -1):
                suf[j] = {q + c for q in suf[j + 1] for c in vals[j]}
            target = round(v * 100)
            tol = int(TOL * 100) + 1
            ok = {i: set() for i in inv}
            for j, i in enumerate(inv):
                good_vals = set()
                for c in vals[j]:
                    rest = target - c
                    if any((rest - p - d) in suf[j + 1] for p in pre[j] for d in range(-tol, tol + 1)):
                        good_vals.add(c)
                for k, c in tabs[j].items():
                    if round(c * 100) in good_vals:
                        ok[i].add(k)
            if all(not ok[i] for i in inv):
                continue  # inconsistent (cap?) -> ignore this equation
            for i in inv:
                if ok[i] and ok[i] < feas[i]:
                    feas[i] = ok[i]
                    changed = True

    out = {}
    for i in items:
        ks = sorted(feas[i])
        lo = reps[i][ks[0]]
        hi = reps[i][ks[-1] + 1] if ks[-1] + 1 < len(reps[i]) else None
        out[i] = {"t_lo": lo, "t_hi": hi, "charges": charges[i]}
    return out


def main(game_id: int) -> None:
    res = infer(game_id)
    print(f"game {game_id}: fair-value bounds (t_lo = proven fair, t_hi = proven fraud)")
    for i, v in res.items():
        hi = "inf" if v["t_hi"] is None else f"{v['t_hi']:.0f}"
        print(f"  item {i:2d}: {v['t_lo']:7.2f} <= t < {hi:>5s}   charges seen: {[round(c) for c in v['charges']]}")
    p = ROOT / "runs" / f"truth_game_{game_id:02d}.json"
    p.write_text(json.dumps(res, indent=1))
    print(f"saved {p.relative_to(ROOT)}")


if __name__ == "__main__":
    gid = int(sys.argv[1])
    try:
        main(gid)
    except (requests.HTTPError, ValueError) as e:
        # 409 from /transactions or game missing from completed list: the game has not closed yet
        print(f"truth: game {gid} is not available on the leaderboard yet ({e.__class__.__name__}); rerun `make truth G={gid}` once it has closed")
        sys.exit(1)

