"""After a game closes: what did everyone charge, who accepted what, how did we do.

  pixi run python -m c2f.feedback 2            # digest game 2
  C2F_TEAM="our name"  (optional; otherwise matched from runs/game_NN.json)

Per item it prints every team's charge a (their t estimate!), how many reviewers
accepted it, and the bounds on each team's acceptance limit b implied by their
accept/reject decisions. Market median of a across teams is a cheap second opinion on t.
"""

from __future__ import annotations

import collections
import functools
import json
import os
import sys
from statistics import median

import requests

from c2f.submit import ROOT

B = "https://c2f.public.quantco.cloud/leaderboard/api"
DEFAULT_TEAM = "AsianSuperNerds" 


FEED_CACHE = ROOT / "runs" / "feed"


@functools.lru_cache(maxsize=1)
def teams() -> list[str]:
    return [t["team_name"] for t in requests.get(f"{B}/matrix?page=1&game_limit=1", timeout=15).json()["items"]]


@functools.lru_cache(maxsize=1)
def completed() -> frozenset[int]:
    """Games the leaderboard reports as finished. Their feed can never change again."""
    try:
        r = requests.get(f"{B}/games", params={"completed_only": True, "page_size": 1000}, timeout=15)
        r.raise_for_status()
        return frozenset(int(g["id"]) for g in r.json()["items"])
    except Exception:  # noqa: BLE001 - no cache is a slowdown, not a failure
        return frozenset()


def transactions(game_id: int, team: str) -> list[dict]:
    """Transactions involving `team` in `game_id`, cached on disk once the game is closed.

    A closed game's feed is immutable, and the callers hammer it: `digest` pulls
    every team, and the tuner calls `digest` once per candidate per game. Without
    this, one `c2f.autotune` run was ~1,800 identical HTTP requests and took
    minutes; with it, everything after the first pass is local.
    """
    cacheable = game_id in completed()
    path = FEED_CACHE / f"g{game_id:02d}_{team.replace('/', '_')}.json"
    if cacheable and path.exists():
        try:
            return json.loads(path.read_text(encoding="utf-8"))
        except (OSError, ValueError):
            pass  # corrupt cache entry: fall through and refetch

    r = requests.get(f"{B}/transactions", params={"game_id": game_id, "team": team, "page_size": 1000}, timeout=15)
    r.raise_for_status()
    items = r.json()["items"]
    if cacheable:
        try:
            FEED_CACHE.mkdir(parents=True, exist_ok=True)
            path.write_text(json.dumps(items), encoding="utf-8")
        except OSError:
            pass  # cache is an optimisation; never fail the caller over it
    return items


def digest(game_id: int) -> dict:
    """amount in the feed is the PAYOUT: accepted -> min(a, c); rejected -> a if fair (a <= t) else 0."""
    names = teams()
    pay: dict[str, dict[int, list]] = collections.defaultdict(lambda: collections.defaultdict(list))  # issuer -> item -> [(reviewer, accepted, payout)]
    seen = set()
    for t in names:
        for x in transactions(game_id, t):
            key = (x["issuer"], x["reviewer"], x["line_item_index"])
            if key in seen:
                continue
            seen.add(key)
            pay[x["issuer"]][x["line_item_index"]].append((x["reviewer"], bool(x["accepted"]), float(x["amount"])))
    items = sorted({i for t in pay for i in pay[t]})
    issued: dict[str, dict[int, float | None]] = collections.defaultdict(dict)  # best guess of a
    fair: dict[str, dict[int, bool | None]] = collections.defaultdict(dict)    # a <= t ?
    t_lo: dict[int, float] = {i: 0.0 for i in items}
    t_hi: dict[int, float] = {i: float("inf") for i in items}
    for iss in names:
        for i in items:
            rows = pay[iss].get(i, [])
            acc_pay = [p for _, a, p in rows if a]
            rej_pay = [p for _, a, p in rows if not a]
            a_guess = max(acc_pay) if acc_pay else (max(rej_pay) if rej_pay and max(rej_pay) > 0 else None)
            issued[iss][i] = a_guess
            if rej_pay:
                if max(rej_pay) > 0:
                    fair[iss][i] = True
                    t_lo[i] = max(t_lo[i], max(rej_pay))
                elif a_guess and a_guess > 0:
                    fair[iss][i] = False
                    t_hi[i] = min(t_hi[i], a_guess)
                elif not acc_pay:
                    fair[iss][i] = None  # rejected everywhere with 0: fraud, but a unknown (>0) or a=0
            else:
                fair[iss][i] = None
    # reviewer limits: accepted a -> b >= a ; rejected a -> b < a
    b_lo: dict[str, dict[int, float]] = collections.defaultdict(dict)
    b_hi: dict[str, dict[int, float]] = collections.defaultdict(dict)
    for iss in names:
        for i in items:
            a = issued[iss][i]
            for rv, acc, _ in pay[iss].get(i, []):
                if a is None:
                    continue
                if acc:
                    b_lo[rv][i] = max(b_lo[rv].get(i, 0.0), a)
                elif a > 0:
                    b_hi[rv][i] = min(b_hi[rv].get(i, float("inf")), a)
    accepted = {iss: {i: [a for _, a, _ in pay[iss].get(i, [])] for i in items} for iss in names}
    return {"teams": names, "items": items, "issued": issued, "fair": fair, "t_lo": t_lo, "t_hi": t_hi,
            "accepted": accepted, "b_lo": b_lo, "b_hi": b_hi, "pay": pay}


def our_team(game_id: int, d: dict) -> str | None:
    if os.environ.get("C2F_TEAM"):
        return os.environ["C2F_TEAM"]
    return DEFAULT_TEAM
    p = ROOT / "runs" / f"game_{game_id:02d}.json"
    if not p.exists():
        return None
    rec = json.loads(p.read_text())
    subs = [s for s in rec.get("submissions", []) if isinstance(s.get("response"), list)]
    if not subs:
        return None
    ours_a = {r["index"]: r["charge_price"] for r in subs[-1]["rows"]}
    ours_b = {r["index"]: r["acceptance_limit"] for r in subs[-1]["rows"]}
    best, best_n = None, -1
    for t in d["teams"]:
        n = 0
        for i in ours_a:
            a = d["issued"][t].get(i)
            if a is not None and abs(a - ours_a[i]) < 0.01:
                n += 2
            lo, hi = d["b_lo"][t].get(i, 0.0), d["b_hi"][t].get(i, float("inf"))
            if lo <= ours_b[i] < hi:
                n += 1
        if n > best_n:
            best, best_n = t, n
    return best if best_n >= len(ours_a) else None


def main(game_id: int) -> None:
    d = digest(game_id)
    us = our_team(game_id, d)
    print(f"game {game_id}: {len(d['teams'])} teams, items {d['items']}   us = {us or '?'}")
    ours = None
    p = ROOT / "runs" / f"game_{game_id:02d}.json"
    if p.exists():
        rec = json.loads(p.read_text())
        subs = [s for s in rec.get("submissions", []) if isinstance(s.get("response"), list)]
        if subs:
            ours = {r["index"]: r for r in subs[-1]["rows"]}
    print(f"{'item':>4} {'t_lo':>7} {'t_hi':>7} {'mkt_med':>7} | {'our a':>7} {'our b':>7}  verdict")
    for i in d["items"]:
        charges = [a for t in d["teams"] for a in [d["issued"][t].get(i)] if a]
        med = median(charges) if charges else 0.0
        lo, hi = d["t_lo"][i], d["t_hi"][i]
        if ours and i in ours:
            a, b = ours[i]["charge_price"], ours[i]["acceptance_limit"]
            v = []
            if a > 0 and hi < float("inf") and a >= hi:
                v.append("a TOO HIGH (fraud)")
            if a > 0 and a <= lo and lo > 0:
                v.append("a fair")
            if b < lo:
                v.append("b TOO LOW (penalties)")
            if hi < float("inf") and b >= hi:
                v.append("b too high (paid fraud)")
            a_s, b_s, v_s = f"{a:7.1f}", f"{b:7.1f}", ", ".join(v) or "-"
        else:
            a_s = b_s = "      ?"
            v_s = "-"
        print(f"{i:>4} {lo:7.0f} {hi if hi < float('inf') else 0:7.0f} {med:7.0f} | {a_s} {b_s}  {v_s}")
    print("\n(t_hi 0 = unknown)  per item, charges by team (a, fair?, accepted):")
    for i in d["items"]:
        cells = []
        for t in d["teams"]:
            a = d["issued"][t].get(i)
            if a:
                f = d["fair"][t].get(i)
                acc = d["accepted"][t][i]
                cells.append(f"{t[:12]}={a:.0f}{'✓' if f else ('✗' if f is False else '?')}({sum(acc)}/{len(acc)})")
        print(f"  #{i}: " + "  ".join(cells))
    if us:
        perf = requests.get(f"{B}/performance", params={"team": us}, timeout=15).json()
        print("\nour performance so far:", json.dumps(perf))
    out = ROOT / "runs" / f"feedback_game_{game_id:02d}.json"
    slim = {k: v for k, v in d.items() if k != "pay"}
    out.write_text(json.dumps(slim, indent=1, default=str))
    print(f"saved {out.relative_to(ROOT)}")


if __name__ == "__main__":
    main(int(sys.argv[1]))

content.content:
"""What the market actually paid, in past games, for line items like these.

c2f.truth recovers a bracket [t_lo, t_hi) per past item from the leaderboard. Our own
t_mid is wrong in category-shaped ways (c2f.accuracy: diagnostics/labour/material come
out ~1.3-1.8x too low, drying/electronics ~2x too high), and a single global bias cannot
fix that because the errors point in opposite directions. So hand the model the evidence
instead: the observed t brackets, grouped by the same buckets c2f.price uses, plus the
handful of labels that recur verbatim across games.

Built once at import from runs/truth_game_*.json + the case in each run log. Best effort:
no truth files, no block, and the prompt is exactly what it was before.
"""

from __future__ import annotations

import collections
import re
import statistics

from c2f.accuracy import rows

MIN_N = 3  # a bucket needs this many observations before it is worth a line
MIN_PAIRED = 3  # ...and this many carrying BOTH bounds before we quote a two-sided band
MAX_LABELS = 12  # recurring labels listed verbatim, most-seen first


def _norm(s: str) -> str:
    return re.sub(r"[^a-z0-9 ]", "", s.lower()).strip()


def _band(obs: list[dict]) -> tuple[float, float | None, int]:
    """Both ends of the band measured over the SAME items, and price signal only.

    Two things went wrong when the ends were medians over whatever happened to carry each
    bound. (1) The subsets are disjoint - ancillary/call-out had 23 floors and 32 ceilings
    but only 13 items with both - so the printed ceiling landed UNDER the printed floor in
    every bucket, while no single item is inverted (0 of 104). (2) A t_hi on an item with
    no proven floor is a COVERAGE refusal, not a price ceiling: the market refused it at
    any price. Those were 69 of 173 ceilings and their median is 41 against 184 for real
    ones, so pooling them taught the model to under-price the covered items too.

    So: only items proven to be worth something carry price signal, and a two-sided band is
    quoted only from the items carrying both bounds. Returns (lo, hi, n_behind_the_band).
    """
    priced = [r for r in obs if r["t_lo"] > 0]
    if not priced:
        return 0.0, None, 0
    paired = [r for r in priced if r["t_hi"] is not None]
    if len(paired) >= MIN_PAIRED:
        return (
            statistics.median(r["t_lo"] for r in paired),
            statistics.median(r["t_hi"] for r in paired),
            len(paired),
        )
    return statistics.median(r["t_lo"] for r in priced), None, len(priced)


def _fmt(lo: float, hi: float | None, n: int) -> str:
    """Never print a range whose ends were not measured on the same items."""
    if lo > 0 and hi is not None:
        return f"fair value sat between ~EUR {lo:.0f} and ~EUR {hi:.0f}  (n={n} with both bounds)"
    if lo > 0:
        return f"paid at least ~EUR {lo:.0f}, never refused  (n={n})"
    return "no price signal - every observation was refused as not covered"


def build() -> str:
    try:
        R = [r for r in rows() if r["description"].strip()]
    except Exception:
        return ""
    if not R:
        return ""

    lines: list[str] = []
    by_bucket = collections.defaultdict(list)
    for r in R:
        by_bucket[r["bucket"]].append(r)
    for b, obs in sorted(by_bucket.items(), key=lambda x: -len(x[1])):
        if b == "other" or len(obs) < MIN_N:
            continue
        lo, hi, n = _band(obs)
        rng = _fmt(lo, hi, n)
        # ratio of what the market proved to what we guessed: >1 = we came in too low
        ratios = sorted(r["t_lo"] / r["t_mid"] for r in obs if r["t_mid"] > 0 and r["t_lo"] > 0)
        hint = ""
        if len(ratios) >= MIN_N:
            med = ratios[len(ratios) // 2]
            if med >= 1.2:
                hint = "  (we habitually UNDER-price this category)"
            elif med <= 0.8:
                hint = "  (we habitually OVER-price this category)"
        lines.append(f"  {b:<20} {rng}{hint}")

    by_label = collections.defaultdict(list)
    for r in R:
        by_label[_norm(r["description"])].append(r)
    repeats = sorted(
        ((k, v) for k, v in by_label.items() if len({x["game"] for x in v}) > 1),
        key=lambda x: -len(x[1]),
    )[:MAX_LABELS]
    label_lines = []
    for k, obs in repeats:
        lo, hi, n = _band(obs)
        label_lines.append(f"  {k[:38]:<40} {_fmt(lo, hi, n)}")

    if not lines and not label_lines:
        return ""
    out = (
        '<market_history note="what the market ACTUALLY accepted for comparable line items in '
        'past rounds of THIS game, recovered from the opponents\' charges. Evidence, not a rule: '
        'this case\'s policy and quantities still decide. Use it to sanity-check the ORDER OF '
        'MAGNITUDE of your t_mid, and be reluctant to land far outside a range with many '
        'observations behind it.">\n'
    )
    if lines:
        out += "by category:\n" + "\n".join(lines) + "\n"
    if label_lines:
        out += "line items that have appeared before, verbatim:\n" + "\n".join(label_lines) + "\n"
    return out + "</market_history>\n\n"


HISTORY = build()


def main() -> int:
    """Snapshot the block the model will see, so a round's change to it is visible and diffable.

    The prompt does NOT read this file - build() runs from runs/truth_game_*.json at import,
    so the block is always current whether or not anyone ran this. The snapshot exists to be
    committed and eyeballed: `git diff runs/market_history.txt` after a round says exactly what
    the new evidence moved.
    """
    from c2f.submit import ROOT

    block = build()
    out = ROOT / "runs" / "market_history.txt"
    if not block:
        print("no truth files yet - no market history to write")
        return 0
    out.write_text(block, encoding="utf-8")
    print(block)
    print(f"saved {out.relative_to(ROOT)}  ({len(block)} chars in every prompt)")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
----
"""One place to read what a finished game left behind.

Every analysis tool (c2f.accuracy, c2f.calibrate, c2f.deviation, c2f.history, c2f.postmortem)
joins the same three things: the model's per-item estimate, the (a, b) board that actually went
out, and the t brackets c2f.truth recovered from the leaderboard. They used to each carry their
own copy of that loading - four `estimates()` functions with two different key precedences
between them, which is a disagreement waiting to matter the day a log carries both keys.
"""

from __future__ import annotations

import json

from c2f.price import bucket_of
from c2f.submit import ROOT

RUNS = ROOT / "runs"

#: run-log keys holding the model's per-item output, newest shape first. `estimate` is what
#: c2f.run writes today; `ensemble` is from when several votes were aggregated; the
#: `model_full*` outputs are the raw pass, used when a run died before it merged one.
ESTIMATE_KEYS = ("estimate", "ensemble", "model_full", "model_full0")


def log(game_id: int) -> dict:
    """The run log for a game (the real one, else a dry run). {} if there is none."""
    for name in (f"game_{game_id:02d}.json", f"dry_game_{game_id:02d}.json"):
        p = RUNS / name
        if p.exists():
            return json.loads(p.read_text(encoding="utf-8"))
    return {}


def estimates_from(rec: dict) -> dict[int, dict]:
    """Per-item model estimate out of an already-loaded run log, indexed by POS.

    The invoice wording rides along as `_description`: the model's own output has no
    description field, and the category is what c2f.price's per-bucket bias keys on.
    """
    src: dict = {}
    for key in ESTIMATE_KEYS:
        v = rec.get(key) or {}
        v = (v.get("output") or {}) if key.startswith("model_") else v
        if v.get("items"):
            src = v
            break
    items = {int(i["index"]): i for i in src.get("items", []) if "index" in i}
    descs = {int(i["index"]): i.get("description", "") for i in rec.get("case", {}).get("items", [])}
    for i, it in items.items():
        it.setdefault("_description", descs.get(i, ""))
    return items


def estimates(game_id: int) -> dict[int, dict]:
    return estimates_from(log(game_id))


def board(game_id: int) -> dict[int, dict]:
    """The (a, b) per item as the server saw them at close: submissions applied in order,
    last write wins - the same rule the scoring uses."""
    rows: dict[int, dict] = {}
    for sub in log(game_id).get("submissions") or []:
        for r in sub.get("rows") or []:
            try:
                rows[int(r["index"])] = r
            except (KeyError, TypeError, ValueError):
                continue
    return rows


def truths(games: list[int] | None = None) -> dict[int, dict]:
    """game id -> {item index: {t_lo, t_hi, ...}} for every game c2f.truth has labelled."""
    out: dict[int, dict] = {}
    for p in sorted(RUNS.glob("truth_game_*.json")):
        g = int(p.stem.split("_")[-1])
        if games is not None and g not in games:
            continue
        out[g] = {int(k): v for k, v in json.loads(p.read_text(encoding="utf-8")).items()}
    return out


def rows(games: list[int] | None = None) -> list[dict]:
    """One row per labelled item: what we estimated against what the market proved.

    `t_hi` is None when the bracket is open above. Callers filter: c2f.calibrate drops rows
    that prove nothing (t_lo <= 0 and no t_hi), c2f.accuracy keeps them to count abstentions.
    """
    out: list[dict] = []
    for g, truth in truths(games).items():
        est = estimates(g)
        for i, tv in truth.items():
            it = est.get(i)
            if not it:
                continue
            try:
                mid = float(it.get("t_mid") or 0)
            except (TypeError, ValueError):
                mid = 0.0
            t_hi = tv.get("t_hi")
            out.append({
                "game": g,
                "item": i,
                "bucket": bucket_of(it.get("_description", "")),
                "description": it.get("_description", ""),
                "covered": bool(it.get("covered")) and bool(it.get("related", True)),
                "t_mid": mid,
                "t_lo": float(tv.get("t_lo") or 0.0),
                "t_hi": float(t_hi) if t_hi is not None else None,
            })
    return out

