        print(f"  {name:16s} n={len(xs):3d} median ln(t/q50)={med:+.2f} MAD={mad:.2f} sd={statistics.pstdev(xs):.2f}  frac t<0.5q50={sum(1 for x in xs if x<math.log(.5))/len(xs):.2f}")
# coverage calibration
print("coverage: p_cov vs proven")
bins=collections.defaultdict(lambda:[0,0])
for r in rows:
    pc=r["pc"]
    if pc is None: continue
    proven_cov = r["lo"]>0
    proven_not = (r["lo"]<=0 and r["hi"] is not None and r["hi"]<60)
    if not (proven_cov or proven_not): continue
    b=min(int(pc*5),4); bins[b][0]+=1; bins[b][1]+=proven_cov
for b in sorted(bins): print(f"  p_cov in [{b/5:.1f},{(b+1)/5:.1f}): n={bins[b][0]} covered={bins[b][1]}")

# 2. field charge ratios r=a_j/t*, per team, and per-team b/t*
ratio=collections.defaultdict(list); bl=collections.defaultdict(list)
for g in range(30,54):
    tp=ROOT/"runs"/f"truth_game_{g:02d}.json"
    if not tp.exists(): continue
    tr=json.load(open(tp))
    try: d=digest(g)
    except Exception as e: print("digest fail",g,e); continue
    for i in d["items"]:
        tv=tr.get(str(i)); 
        if not tv: continue
        lo,hi=float(tv.get("t_lo") or 0),tv.get("t_hi")
        if lo>0 and hi: t=math.sqrt(lo*hi)
        elif lo>0: t=lo*1.1
        else: continue
        for team in d["teams"]:
            a=d["issued"][team].get(i)
            if a and a>0: ratio[team].append(a/t)
            blo,bhi=d["b_lo"][team].get(i,0.0),d["b_hi"][team].get(i,float("inf"))
            if blo>0 and bhi<float("inf"): bl[team].append(math.sqrt(blo*bhi)/t)
            elif blo>0: bl[team].append(blo/t*1.1)
            elif bhi<float("inf"): bl[team].append(bhi/t*0.8)
allr=[x for v in ratio.values() for x in v]
q=lambda xs,p: sorted(xs)[int(p*(len(xs)-1))]
print(f"\nfield charge ratio a/t*: n={len(allr)} q10={q(allr,.1):.2f} q25={q(allr,.25):.2f} q50={q(allr,.5):.2f} q63={q(allr,.63):.2f} q75={q(allr,.75):.2f} q90={q(allr,.9):.2f}  P(r<=1)={sum(1 for x in allr if x<=1)/len(allr):.2f}")
print("per team: n, median a/t*, P(fair), median b/t*, P(b>=t)")
for team in sorted(ratio, key=lambda t:-len(ratio[t])):
    r=ratio[team]; b=bl.get(team,[])
    print(f"  {team[:20]:20s} n={len(r):3d} med a/t={q(r,.5):.2f} P(fair)={sum(1 for x in r if x<=1)/len(r):.2f}  | b n={len(b):3d} med b/t={q(b,.5) if b else float('nan'):.2f} P(b>=t)={sum(1 for x in b if x>=1)/max(1,len(b)):.2f}")
